INSERT INTO dictionary_item (created_at, updated_at, type, label, active) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 'METRIC_NAME', 'Weight', TRUE WHERE NOT EXISTS ( SELECT 1 FROM dictionary_item WHERE type = 'METRIC_NAME' AND label = 'Weight' );
