INSERT INTO metric_name_unit_link (created_at, updated_at, metric_name_id, metric_unit_id) SELECT CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, metric_name.id, metric_unit.id FROM dictionary_item metric_name JOIN dictionary_item metric_unit ON metric_unit.type = 'METRIC_UNIT' WHERE metric_name.type = 'METRIC_NAME' AND metric_name.label = 'Weight' AND metric_unit.label = 'kg' AND NOT EXISTS ( SELECT 1 FROM metric_name_unit_link link WHERE link.metric_name_id = metric_name.id AND link.metric_unit_id = metric_unit.id );
